head.script:
scwin.screenId = "jldstf07150";

///////// 1. 변수 및 선언 영역 /////////

scwin.isChkBzCalnd = false;

scwin.form = null;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "* 우회상장법인 정보(" + String(dma_commonInfo.get("apComNm")) + ")"; } },
        { childId: "ipt_bzProcsNo", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bzProcsNo"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.onload();
        try {
            const resultLen = $c.util.getComponent('dlt_resultList').getTotalRow();
            for (let i = 0; i < resultLen; i++) {
                if (i < (resultLen - 1)) {
                    if (scwin.form.pershrInvstSaleTotDsp[i] != null) {

                    }
                }
            }
        } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldstf07150' }); }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07150.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldstf07150: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.maxLenCheckVars = undefined; try { scwin.maxLenCheckVars = /* sdd-asis-lifecycle:begin maxLenCheckVars — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07150' }); }

scwin.maxLenCheckNames = undefined; try { scwin.maxLenCheckNames = /* sdd-asis-lifecycle:begin maxLenCheckNames — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07150' }); }

scwin.maxLenCheckMax = undefined; try { scwin.maxLenCheckMax = /* sdd-asis-lifecycle:begin maxLenCheckMax — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07150' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07150.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07150.btn_print_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_resultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.loadCapital === 'function') { scwin.loadCapital(r["bzProcsNo"], r["clmInstSeq"], r["comNm"], r["invstChgTpCd"], r["invstDd"], r["invstSaleShrs"], r["pershrInvstSaleAmt"], r["stkNm"], r["incdecRsn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.loadCapital (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.loadCapital'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name scwin.onload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onload = function () {
    /* sdd-asis-lifecycle:begin fn_Onload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.prelistEtcForm || { elements: [] });
    /* sdd-asis-lifecycle:end */
};



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_resultList_fmt_invstDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_resultList_fmt_invstDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bzProcsNo") ?? '') : '');
        if (v !== 'SUMPART') { return String((dl && dl.getCellData ? dl.getCellData(r, "invstDd") : '') ?? ''); }
        if (v === 'SUMPART') { return "소계"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.invstDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.loadCapital
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo clmInstSeq comNm invstChgTpCd invstDd invstSaleShrs pershrInvstSaleAmt stkNm incdecRsn
 * @returns
 * @hidden N
*/
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    /* sdd-asis-lifecycle:begin fn_LoadCapital — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    (($c.util.getComponent('slc_invstChgTpCd'))?.setValue?.(invstChgTpCd));
    $c.util.getComponent('ipt_invstDd').setValue($c.date.dateUnFormat(invstDd));
    $c.util.getComponent('ipt_invstSaleShrs').setValue($c.num.formatNumber(invstSaleShrs));
    $c.util.getComponent('ipt_pershrInvstSaleAmt').setValue($c.num.formatNumber(pershrInvstSaleAmt));
    (($c.util.getComponent('slc_stkNm'))?.setValue?.(stkNm));
    (($c.util.getComponent('slc_incdecRsn'))?.setValue?.(incdecRsn));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setDataMergeDate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setDataMergeDate = function () {
    /* sdd-asis-lifecycle:begin fn_SetDataMerge_Date — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    /* empty */
    /* sdd-asis-lifecycle:end */
};
